const now = new Date();
const since = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const commits = $input.all()[0]?.json || [];
const issues = $input.all()[1]?.json || [];

const commitMessages = commits.map(c => '- ' + (c.commit?.message?.split('\n')[0] || c.sha?.slice(0,7))).slice(0, 30);
const mergedPRs = issues.filter(i => i.pull_request && i.pull_request.merged_at).map(i => '- #' + i.number + ' ' + i.title).slice(0, 20);
const closedIssues = issues.filter(i => !i.pull_request && i.state === 'closed').map(i => '- #' + i.number + ' ' + i.title).slice(0, 15);
const openIssues = issues.filter(i => !i.pull_request && i.state === 'open').map(i => '- #' + i.number + ' ' + i.title).slice(0, 15);

return [{
  json: {
    repo: $input.first().json.repo || 'unknown',
    owner: $input.first().json.owner || 'unknown',
    since: since.toISOString(),
    to: now.toISOString(),
    commitCount: commits.length,
    prCount: mergedPRs.length,
    closedIssueCount: closedIssues.length,
    openIssueCount: openIssues.length,
    commitMessages: commitMessages.join('\n'),
    mergedPRs: mergedPRs.join('\n'),
    closedIssues: closedIssues.join('\n'),
    openIssues: openIssues.join('\n')
  }
}];

