const summary = $input.first().json.content || $input.first().json.message?.content || $input.first().json.text || JSON.stringify($input.first().json);
const repo = $input.first().json.repo || 'repo';
const week = new Date().toISOString().slice(0, 10);
return [{
  json: {
    filename: `weekly-summary-${repo}-${week}.md`,
    content: `# Weekly Dev Summary: ${repo} (${week})\n\n${summary}\n\n_Generated by n8n + Claude_`,
    summary
  }
}];
